    async importBackup(text) {
      let data;
      try { data = JSON.parse(text); } catch (_) { throw new Error('This is not a contacts backup.'); }
      if (data?.format !== 'livu-contacts-v1' || !Array.isArray(data.contacts) || data.contacts.length > 2000) {
        throw new Error('Choose a LivU contacts backup with at most 2,000 contacts.');
      }
      // Validate the entire file before changing storage. Ignore all sync IDs and flags supplied by a file.
      const clean = data.contacts.map(contact);
      const unique = new Map(clean.map(x => [x.url, x]));
      for (const item of unique.values()) await this.save(item);
      return unique.size;
    }
    async backup() {
      return JSON.stringify({ format: 'livu-contacts-v1', contacts: (await this.all()).map(contact) }, null, 2);
    }
