    if (!['check', 'send', 'unlock'].includes(request.operation) || !validId(request.contactId) || !unchanged()) return interrupted();
    if (request.contactId === owner()) return { state: 'skipped', message: 'This is your signed-in account.' };
    if (app().showVideoPop || app().show1v1Pop || app().showLive) {
      return { state: 'skipped', stop: true, message: 'Finish your current call before sending greetings.' };
    }
    if (boxes().some(draft)) return { state: 'skipped', stop: true, message: 'Your existing message draft is kept. Send or clear it first.' };
    let relation;
    // window.$api is the Axios instance; its get() needs a params config.
    try { relation = await env.$api.get('/facade/api/friend/relations', { params: { friendUserId: Number(request.contactId) }, timeout: 12000 }); }
    catch (error) { return unchanged() ? { state: 'skipped', stop: true, message: 'Could not check this contact (' +
      readFailure(error, 'friendUserId', request.contactId) + '). No message was sent. Remaining greetings paused.' } : interrupted(); }
    if (!unchanged()) return interrupted();
    if (relation?.code !== 200 || !Number.isInteger(relation.data) || ![0, 1, 2, 3, 4].includes(relation.data)) {
      return { state: 'skipped', message: 'LivU did not confirm a free chat for this contact' +
        (Number.isSafeInteger(relation?.code) ? ' (code ' + relation.code + ')' : '') + '. No message was sent.' };
    }
    if (boxes().some(draft)) return { state: 'skipped', stop: true, message: 'Your existing message draft is kept. Send or clear it first.' };
    if (app().showVideoPop || app().show1v1Pop || app().showLive) return { state: 'skipped', stop: true, message: 'Finish your current call before sending greetings.' };
    if (request.operation === 'unlock') {
      if (request.approvedCoins !== 9) return { state: 'skipped', message: 'Paid chat was not approved. No coins spent.' };
      if (relation.data !== 4) return { state: 'ready' };
      let paid;
      try { paid = await env.$api.post('/facade/api/friend/addFriend', { addWay: 102, friendUserId: Number(request.contactId), addReally: true }); }
      catch (_) { return { state: 'uncertain', message: 'The paid friend-add response was lost. Check your coins and chat manually; no automatic retry.' }; }
      if (paid?.code === 200) return { state: 'unlocked', stop: !unchanged(), message: 'LivU accepted the 9-coin friend addition.' };
      if (Number.isInteger(paid?.code)) return { state: 'rejected', message: 'LivU rejected the paid friend-add (code ' + paid.code + '). No message was sent.' };
      return { state: 'uncertain', message: 'The paid friend-add was not confirmed. Check your coins and chat manually; no automatic retry.' };
    }
    if (relation.data === 4) return request.alreadyUnlocked ?
      { state: 'skipped', message: 'Friend addition was already accepted, but LivU has not opened the chat yet. No repeat charge.' } :
      { state: 'approval-required', coins: 9, message: 'LivU requires a 9-coin friend addition to open this chat.' };
